      continue;
    }
    ui.jobs.push({
      id: `job_${Math.random().toString(36).slice(2, 9)}`,
      file,
      state: "queued",
      pct: 0,
      stage: "En cola",
    });
  }
  if (ignored.length) {
    toast(`No sé leer ${ignored.length === 1 ? "este archivo" : "estos archivos"} (${ignored.slice(0, 2).join(", ")}). Solo fotos y PDF.`, "bad", 5200);
