async function runQueue() {
  if (runningQueue) return;
  runningQueue = true;
  try {
    for (;;) {
      const job = ui.jobs.find((j) => j.state === "queued");
      if (!job) break;
      await runOne(job);
    }
  } finally {
    runningQueue = false;
    paintIngest();
  }
}

